{
  "schema_version": "sections_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "sections": [
        {
          "section_id": 1,
          "title": "Office Space to Outer Space",
          "intent": "Establish Artie's mundane life and the jarring transition to the System interface.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie completes the character creation process and stands in the world of Aethelgard."
        },
        {
          "section_id": 2,
          "title": "The Tutorial Bug",
          "intent": "Introduce the combat system and reveal Artie's 'Glitch-Crit' during a scripted tutorial boss.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "The tutorial boss is defeated via an unintended mechanical exploit."
        },
        {
          "section_id": 3,
          "title": "Resource Management",
          "intent": "Highlight the instability of the class and the immediate need for rare resources.",
          "section_role": "payoff",
          "target_scene_count": 3,
          "end_condition": "Artie identifies the specific rare resources required to stabilize his class."
        }
      ]
    },
    {
      "chapter_id": 2,
      "sections": [
        {
          "section_id": 1,
          "title": "The Grind is Real",
          "intent": "Show Artie attempting to play the game normally before discovering a loot exploit.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie triggers a recursive loot loop in the Whispering Woods."
        },
        {
          "section_id": 2,
          "title": "Looting the World Dry",
          "intent": "Demonstrate the absurdity of the exploit as Artie inadvertently strips the dungeon of all value.",
          "section_role": "development",
          "target_scene_count": 3,
          "end_condition": "The Whispering Woods dungeon is rendered completely empty of items and monsters."
        },
        {
          "section_id": 3,
          "title": "Market Crash",
          "intent": "Show the consequences of Artie's actions on the local economy and the Guild's response.",
          "section_role": "payoff",
          "target_scene_count": 2,
          "end_condition": "Artie observes the Adventurers' Guild arriving to investigate the 'looted' dungeon."
        }
      ]
    },
    {
      "chapter_id": 3,
      "sections": [
        {
          "section_id": 1,
          "title": "The Stability Tax",
          "intent": "Heighten the stakes by showing Artie's class meter reaching a critical failure point.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie locates the 'Cooldown Reset' gem within the city's high-security vault."
        },
        {
          "section_id": 2,
          "title": "The Vault Heist",
          "intent": "A comedic but high-stakes infiltration where Artie uses glitches to bypass security.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "Artie successfully acquires the Cooldown Reset gem."
        },
        {
          "section_id": 3,
          "title": "Burn the Bridge",
          "intent": "The chase through the city as Artie is identified as a criminal.",
          "section_role": "payoff",
          "target_scene_count": 3,
          "end_condition": "Artie escapes through the city gates with the guard in pursuit."
        }
      ]
    },
    {
      "chapter_id": 4,
      "sections": [
        {
          "section_id": 1,
          "title": "Welcome to the Glitch",
          "intent": "Introduce the 'Dead Zones' and their reality-warping mechanics.",
          "section_role": "setup",
          "target_scene_count": 4,
          "end_condition": "Artie enters the heart of a Dead Zone where the System is visibly broken."
        },
        {
          "section_id": 2,
          "title": "Logic Errors",
          "intent": "Survival against corrupted mobs and environmental bugs that test Artie's adaptability.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "Artie survives a major reality-warping environmental hazard."
        },
        {
          "section_id": 3,
          "title": "Safe Mode",
          "intent": "The discovery of a sanctuary that offers temporary respite and lore about his class.",
          "section_role": "payoff",
          "target_scene_count": 4,
          "end_condition": "Artie finds and enters the hidden sanctuary."
        }
      ]
    },
    {
      "chapter_id": 5,
      "sections": [
        {
          "section_id": 1,
          "title": "The Anti-Glitched",
          "intent": "Introduce the Bounty Hunter and the threat of 'Nullification'.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The Bounty Hunter successfully corners Artie and disables his glitch abilities."
        },
        {
          "section_id": 2,
          "title": "Back to Basics",
          "intent": "A tactical fight where Artie must rely on fundamental player skill rather than exploits.",
          "section_role": "development",
          "target_scene_count": 4,
          "end_condition": "Artie defeats the Bounty Hunter using clever use of the environment."
        },
        {
          "section_id": 3,
          "title": "The Scout's Warning",
          "intent": "Reveal that the hunter was only the beginning of a larger organized pursuit.",
          "section_role": "payoff",
          "target_scene_count": 2,
          "end_condition": "Artie realizes he is being hunted by a major guild."
        }
      ]
    },
    {
      "chapter_id": 6,
      "sections": [
        {
          "section_id": 1,
          "title": "Storming the Lair",
          "intent": "The approach to the regional boss's lair, fighting through elite guardians.",
          "section_role": "setup",
          "target_scene_count": 4,
          "end_condition": "Artie reaches the inner sanctum of the regional boss."
        },
        {
          "section_id": 2,
          "title": "The One-Percent Roll",
          "intent": "The final confrontation with the boss, requiring a massive, high-risk glitch to win.",
          "section_role": "development",
          "target_scene_count": 5,
          "end_condition": "The regional boss is defeated and the Stability Patch is dropped."
        },
        {
          "section_id": 3,
          "title": "Critical Exposure",
          "intent": "The immediate aftermath where the victory triggers a global System alert.",
          "section_role": "payoff",
          "target_scene_count": 3,
          "end_condition": "Artie's exact location is broadcast to the entire world."
        }
      ]
    },
    {
      "chapter_id": 7,
      "sections": [
        {
          "section_id": 1,
          "title": "Patching the Hole",
          "intent": "Artie uses the loot to permanently stabilize his class mechanics.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "The 'Stability Patch' is successfully integrated into Artie's character sheet."
        },
        {
          "section_id": 2,
          "title": "The Deletion Event",
          "intent": "The System begins a zone reset to purge the anomaly (Artie).",
          "section_role": "development",
          "target_scene_count": 3,
          "end_condition": "Artie narrowly escapes the collapsing zone."
        },
        {
          "section_id": 3,
          "title": "New Region, New Problems",
          "intent": "Set the stage for the next book as Artie enters a new territory.",
          "section_role": "payoff",
          "target_scene_count": 2,
          "end_condition": "Artie crosses the border into the next region as a global target."
        }
      ]
    }
  ]
}

